-- ============================================================
-- WSC N2 — Design-factor catalog seed (2026-07-04)
-- North Star re-founding, phase N2. Seeds the citable engineering factors
-- (research 2026-07-04, adversarially verified — 5 corrections applied)
-- into ref_planning_ratios under four new wsc_* categories.
--
-- Governance (Brock 2026-07-04): CM House-Assumptions pinning pattern —
-- scenarios pin these at first use (config_data.pinnedFactors), drift
-- badge on catalog change, explicit adopt.
-- Flue default (Brock 2026-07-04): FM Global DS 8-9.
--
-- Provenance convention in `source`:
--   standard | industry method | vendor heuristic | IES assumption
-- Idempotent by REPLACE: the natural-key unique index treats NULLs as
-- distinct, so ON CONFLICT can't dedupe these rows — instead the seed
-- deletes its own namespace (ratio_code LIKE 'wsc.%') and re-inserts.
-- ============================================================

DELETE FROM ref_planning_ratios WHERE ratio_code LIKE 'wsc.%';

INSERT INTO ref_heuristic_categories (code, display_name, description, sort_order) VALUES
  ('wsc_media_selection',   'WSC — Storage media selection',   'Depth-of-inventory thresholds, occupancy floors, density gains, cost bands driving engineered media selection', 190),
