  ('wsc_layout_compliance', 'WSC — Layout & compliance',       'Flue spaces (FM vs NFPA), egress, sprinkler clearance, column-grid coordination', 210),
  ('wsc_profile_defaults',  'WSC — Profile & height economics','Sparse-mode defaults, growth buffers, clear-height economics', 220)
ON CONFLICT (code) DO NOTHING;

