('wsc_media_selection','wsc.media.cost_per_position_usd','Cost per pallet position (equipment, 2025–26 USD)','Purchase cost bands by media, hardware only (excl. install/permits/seismic).','lookup',NULL,'USD/position','{"selective":{"min":80,"max":120},"drive_in":{"min":60,"max":110},"pushback":{"min":150,"max":400},"pallet_flow":{"min":250,"max":500},"shuttle_rack":{"min":300,"max":412},"shuttle_bot_each":{"min":30000,"max":40000}}'::jsonb,'industry method','Hammerhead pricing guide 2026-03 + verification corrections (SRS, 3D Storage)','2026-03-01',80,'Pallet-flow band verification-CORRECTED from $550–850 → $250–500. Seismic adds 20–30%.'),
